import { GoogleGenAI, Type } from "@google/genai";
import type { Game } from "../types";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Optimized schema to prioritize real-time injury data and high-fidelity props.
 */
