      required: ["total", "wins", "avgMargin"]
    },
    injuryReport: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          player: { type: Type.STRING },
          status: { type: Type.STRING },
          impactScore: { type: Type.INTEGER, description: "1-10 impact on game outcome" },
          analysis: { type: Type.STRING }
        },
        required: ["player", "status", "impactScore"]
      }
    },
    eliteSignal179: { type: Type.BOOLEAN },
    analysis: { type: Type.STRING },
