export const getSchedule = async (sport: string): Promise<Game[]> => {
  const ai = getAI();
  const today = new Date().toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' });

  const prompt = `Search for ${sport} games occurring TODAY, ${today}. Return STRICT JSON: { "games": [{ "id": "string", "homeTeam": "string", "awayTeam": "string", "league": "${sport}", "time": "string", "date": "Today", "status": "Scheduled|Live|Finished", "score": "optional string", "odds": { "spread": "string", "moneyline": "string", "total": "string" } }] }`;

  const configWithSearch = { 
    tools: [{ googleSearch: {} }],
    temperature: 0.1,
    responseMimeType: 'application/json'
  };

  const configWithoutSearch = {
    temperature: 0.1,
    responseMimeType: 'application/json'
  };

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: configWithSearch as any
    });
    const data = JSON.parse(response.text || '{}');
    return data.games || [];
  } catch (error: any) {
    const isQuotaError = error?.status === 'RESOURCE_EXHAUSTED' || error?.message?.includes('quota');
    if (isQuotaError) {
      try {
        const fallbackResponse = await ai.models.generateContent({
          model: 'gemini-3-flash-preview',
          contents: `${prompt}\n\nNOTE: Search is restricted. Use your internal knowledge to simulate current likely games for today in ${sport}.`,
          config: configWithoutSearch as any
        });
        const data = JSON.parse(fallbackResponse.text || '{}');
        return data.games || [];
      } catch (fallbackError) {
        return [];
      }
    }
    return [];
  }
};

import React, { useState, useCallback, useEffect } from 'react';
import { Header } from './components/Header';
import { SportSelector } from './components/SportSelector';
import { GameSchedule } from './components/GameSchedule';
import { PredictionDisplay } from './components/PredictionDisplay';
import { Loader } from './components/Loader';
import { Footer } from './components/Footer';
import { SettingsModal } from './components/SettingsModal';
import { TokenomicsModal } from './components/TokenomicsModal';
import { ChatInterface } from './components/ChatInterface';
import { SuggestionChips } from './components/SuggestionChips';
import { PickSlip } from './components/PickSlip';
import { PerformanceSidebar } from './components/PerformanceSidebar';
import { VaultView } from './components/VaultView';
import { GoogleGenAI } from "@google/genai";
import { predictionSchema } from './services/geminiService';
import type { Prediction, UserSettings, ChatMessage, Game, PropBet, SavedMatchup } from './types';
import type { Chat } from '@google/genai';

const App: React.FC = () => {
  const [settings, setSettings] = useState<UserSettings>(() => {
    try {
      const storedSettings = localStorage.getItem('prognosSettings');
      if (storedSettings) return JSON.parse(storedSettings);
    } catch (e) { console.error(e); }
    return { preferredSport: 'NFL', defaultConfidenceFilter: 'All', oddsFormat: 'American' };
  });

  const [selectedSport, setSelectedSport] = useState<string>(settings.preferredSport);
  const [selectedGame, setSelectedGame] = useState<Game | null>(null);
  const [prediction, setPrediction] = useState<Prediction | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [isReplying, setIsReplying] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [isSettingsOpen, setIsSettingsOpen] = useState<boolean>(false);
  const [isTokenModalOpen, setIsTokenModalOpen] = useState<boolean>(false);
  const [isHistorySidebarOpen, setIsHistorySidebarOpen] = useState<boolean>(true);
  const [chat, setChat] = useState<Chat | null>(null);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [showSuggestions, setShowSuggestions] = useState<boolean>(false);
  const [pickSlip, setPickSlip] = useState<PropBet[]>([]);
  const [view, setView] = useState<'Feed' | 'Vault'>('Feed');
  const [vault, setVault] = useState<SavedMatchup[]>(() => {
    const saved = localStorage.getItem('prognosVault');
    return saved ? JSON.parse(saved) : [];
  });

  useEffect(() => { setSelectedSport(settings.preferredSport); }, [settings.preferredSport]);
  useEffect(() => {
    setSelectedGame(null);
    setPrediction(null);
    setMessages([]);
    setChat(null);
  }, [selectedSport]);

  useEffect(() => {
    localStorage.setItem('prognosVault', JSON.stringify(vault));
  }, [vault]);

  const addToVault = useCallback((newPrediction: Prediction, game: Game) => {
    if (!newPrediction.props) return;

    const sortedProps = [...newPrediction.props].sort((a, b) => {
      const probA = parseInt(a.probability) || 0;
      const probB = parseInt(b.probability) || 0;
      return probB - probA;
    });

    const entry: SavedMatchup = {
      id: `${game.id}-${Date.now()}`,
      timestamp: Date.now(),
      homeTeam: game.homeTeam,
      awayTeam: game.awayTeam,
      winner: newPrediction.winner,
      confidence: newPrediction.confidence,
      confidenceScore: newPrediction.confidenceScore,
      elitePair: sortedProps.slice(0, 2)
    };

    setVault(prev => [entry, ...prev.filter(v => !v.id.startsWith(game.id))].slice(0, 4));
  }, []);

  const handlePredict = useCallback(async (isRetry = false) => {
    if (!selectedGame) return;
    setIsLoading(true);
    setError(null);

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    try {
      const config: any = {
        systemInstruction: `You are the PRO-N-OS 179-Point Simulation Engine.

        MANDATORY FIRST STEP: Perform a high-intensity sweep of the LATEST (last 2-6 hours) injury reports, inactive lists, and late scratches for both teams. Ground your analysis on verified market news.

        TASK: Run a 179-point variance sweep for this matchup based on ACTUAL roster availability.

        ANALYTIC REQUIREMENTS:
        1. WIN PROBABILITY: Calculate based on current medical status impact.
        2. INJURY REPORT: For every key inactive or questionable player, assign a '1-10 Impact Score' indicating how much their absence shifts the expected point spread.
        3. HIT RATES: Every player prop MUST account for increased/decreased volume due to teammates being out.
        4. MARKET VALUE: Compare your simulation spread to sharp money lines (Pinnacle/Circa).`,
        responseSchema: predictionSchema,
        responseMimeType: 'application/json',
      };

      if (!isRetry) {
        config.tools = [{ googleSearch: {} }];
      }

      const newChat = ai.chats.create({ 
        model: 'gemini-3-pro-preview',
        config
      });

      const response = await newChat.sendMessage({ 
        message: `RUN ELITE 179-POINT SIMULATION with FULL ROSTER & INJURY AUDIT: ${selectedGame.homeTeam} vs ${selectedGame.awayTeam}.` 
      });

      const text = response.text;
      if (!text) throw new Error("Empty AI response");

      try {
        const parsed = JSON.parse(text);
        setPrediction(parsed);
        addToVault(parsed, selectedGame);
        setMessages([{ role: 'model', content: parsed }]);
        setChat(newChat);
        setShowSuggestions(true);
      } catch (jsonErr) {
        if (!isRetry) {
          handlePredict(true);
        } else {
          setError("Engine synchronization failed. Market data was too volatile.");
        }
      }
    } catch (err: any) {
      const isQuotaError = err?.status === 'RESOURCE_EXHAUSTED' || err?.message?.includes('quota');
      if (isQuotaError && !isRetry) {
        handlePredict(true);
      } else {
        setError("Simulation Engine timed out. Market variance is too high.");
      }
    } finally {
      if (!isRetry) setIsLoading(false);
    }
  }, [selectedGame, addToVault, error]);

  const handleSendMessage = useCallback(async (text: string) => {
    if (!chat) return;
    const userMsg: ChatMessage = { role: 'user', content: text };
    setMessages(prev => [...prev, userMsg]);
    setIsReplying(true);
    try {
        const response = await chat.sendMessage({ message: text });
        setMessages(prev => [...prev, { role: 'model', content: response.text || "I couldn't refine that data." }]);
    } catch (e) {
        setMessages(prev => [...prev, { role: 'model', content: "Engine sync lost. Please refresh feed." }]);
    } finally {
        setIsReplying(false);
    }
  }, [chat]);

  return (
    <div className="min-h-screen bg-black text-white font-sans selection:bg-amber-500/30 overflow-x-hidden">
      <Header 
        onOpenSettings={() => setIsSettingsOpen(true)} 
        onOpenToken={() => setIsTokenModalOpen(true)} 
        currentView={view}
        onSetView={setView}
        vaultCount={vault.length}
      />
      <main className={`container mx-auto px-4 py-6 max-w-4xl transition-all duration-500 ${isHistorySidebarOpen && pickSlip.length > 0 ? 'md:pr-[300px]' : ''}`}>
        {view === 'Vault' ? (
            <VaultView vault={vault} onClear={() => setVault([])} onRemove={(id) => setVault(v => v.filter(x => x.id !== id))} />
        ) : (
            <>
                {error && (
                    <div className="bg-red-900/40 border border-red-500/30 text-red-100 px-4 py-3 rounded-xl mb-6 flex justify-between items-center animate-fade-in">
                        <span className="text-xs font-bold uppercase tracking-tight">{error}</span>
                        <button onClick={() => setError(null)} className="text-xl">&times;</button>
                    </div>
                )}
                {!prediction && messages.length === 0 && !isLoading ? (
                    <div className="space-y-8">
                        <SportSelector selectedSport={selectedSport} onSelectSport={setSelectedSport} />
                        <GameSchedule sport={selectedSport} selectedGame={selectedGame} onSelectGame={setSelectedGame} />
                        {selectedGame && (
                            <div className="fixed bottom-10 left-0 right-0 p-4 flex justify-center z-20">
                                <button onClick={() => handlePredict(false)} className="bg-gradient-to-r from-amber-500 to-orange-600 text-black font-black text-lg py-5 px-14 rounded-full shadow-[0_0_50px_rgba(245,158,11,0.5)] transform hover:scale-105 transition-all flex items-center gap-3">
                                    <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
                                    RUN ELITE SIMULATION
                                </button>
                            </div>
                        )}
                    </div>
                ) : isLoading ? <Loader /> : (
                    <div className="space-y-4">
                        <button onClick={() => { setPrediction(null); setMessages([]); setChat(null); }} className="text-stone-500 hover:text-white mb-2 text-xs font-black uppercase tracking-widest flex items-center gap-2">
                            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg> Back to Feed
                        </button>
                        <ChatInterface messages={messages} isReplying={isReplying} onSendMessage={handleSendMessage} oddsFormat={settings.oddsFormat} pickSlip={pickSlip} onTogglePick={(p) => setPickSlip(prev => prev.includes(p) ? prev.filter(x => x !== p) : [...prev, p])} />
                        {showSuggestions && prediction && <SuggestionChips prediction={prediction} onSelect={handleSendMessage} />}
                    </div>
                )}
            </>
        )}
      </main>
      <PerformanceSidebar isOpen={isHistorySidebarOpen && pickSlip.length > 0} activePicks={pickSlip} onClose={() => setIsHistorySidebarOpen(false)} />
      <PickSlip 
        picks={pickSlip} 
        onRemove={(p) => setPickSlip(prev => prev.filter(x => x !== p))} 
        onAnalyze={() => {
          handleSendMessage("Analyze my slip risk using 179-point variance.");
          setIsHistorySidebarOpen(true);
        }} 
      />
      <Footer />
      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} currentSettings={settings} onSave={(s) => { setSettings(s); setIsSettingsOpen(false); }} />
      <TokenomicsModal isOpen={isTokenModalOpen} onClose={() => setIsTokenModalOpen(false)} />
    </div>
  );
};

export default App;

import React, { memo, useState, useMemo } from 'react';
import type { Prediction, OddsFormat, PropBet, BookLine } from '../types';
import { AnalyticsIcon, PlusIcon, CheckIcon, DoubleCheckIcon } from './Icons';

interface PredictionDisplayProps {
  prediction: Prediction;
  oddsFormat: OddsFormat;
  onAnalyzeProp?: (prop: PropBet) => void;
  pickSlip?: PropBet[];
  onTogglePick?: (prop: PropBet) => void;
  onSearchPlayer?: (player: string) => void;
}

const confidenceStyles: Record<string, { bg: string; text: string; border: string; accent: string; glow: string }> = {
    High: { bg: 'bg-green-950/20', text: 'text-green-400', border: 'border-green-500/30', accent: 'bg-green-500', glow: 'shadow-[0_0_30px_rgba(34,197,94,0.2)]' },
    Medium: { bg: 'bg-amber-950/20', text: 'text-amber-400', border: 'border-amber-500/30', accent: 'bg-amber-500', glow: 'shadow-[0_0_30px_rgba(245,158,11,0.2)]' },
    Low: { bg: 'bg-zinc-900/40', text: 'text-zinc-400', border: 'border-zinc-800', accent: 'bg-zinc-600', glow: 'shadow-none' },
};

const isBetterOdds = (oddsA: string, oddsB: string): boolean => {
  const parseOdds = (o: string) => {
    const val = parseInt(o.replace(/[^0-9-]/g, ''));
    if (isNaN(val)) return -Infinity;
    return val;
  };
  const valA = parseOdds(oddsA);
  const valB = parseOdds(oddsB);
  if (valA > 0 && valB > 0) return valA > valB;
  if (valA < 0 && valB < 0) return valA > valB;
  return valA > valB;
};

const getBestOdds = (lines: BookLine[]): string | null => {
  if (!lines || lines.length === 0) return null;
  let best = lines[0];
  for (let i = 1; i < lines.length; i++) {
    if (isBetterOdds(lines[i].odds, best.odds)) {
      best = lines[i];
    }
  }
  return best.book;
};

