             <div className="flex items-center gap-3 mb-4">
                <div className="bg-red-500/10 p-2 rounded-full border border-red-500/30">
                    <svg className="w-4 h-4 text-red-500" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
                </div>
                <h4 className="text-[10px] font-black uppercase tracking-[0.3em] text-red-500">Critical Medical & Roster Alert</h4>
             </div>
             <div className="grid gap-3">
                {prediction.injuryReport.map((injury, i) => (
                    <div key={i} className="bg-black/40 border border-white/5 p-3 rounded-xl flex justify-between items-center group">
                        <div className="flex items-center gap-3">
                            <div className="flex flex-col">
                                <span className="text-xs font-black text-white uppercase">{injury.player}</span>
                                <span className="text-[9px] font-bold text-zinc-500 uppercase tracking-widest">{injury.status}</span>
                            </div>
