import React, { useState, useEffect, memo, useMemo, useRef } from 'react';
import type { Game } from '../types';
import { getSchedule } from '../services/geminiService';

interface GameScheduleProps {
  sport: string;
  selectedGame: Game | null;
  onSelectGame: (game: Game) => void;
}

export const GameSchedule: React.FC<GameScheduleProps> = memo(({ sport, selectedGame, onSelectGame }) => {
  const [games, setGames] = useState<Game[]>([]);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);

  const fetchGames = async () => {
    setIsLoading(true);
    setError(null);
    try {
      const fetchedGames = await getSchedule(sport);
      if (fetchedGames && fetchedGames.length > 0) setGames(fetchedGames);
      else setError(`No ${sport} matchups found for today.`);
    } catch (err) {
      setError('Network sync interrupted.');
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => { fetchGames(); }, [sport]);

  const sortedGames = useMemo(() => {
    return [...games].sort((a, b) => {
      const statusOrder = { 'Live': 0, 'Scheduled': 1, 'Finished': 2 };
      return (statusOrder[a.status] ?? 3) - (statusOrder[b.status] ?? 3);
    });
  }, [games]);

  if (isLoading && games.length === 0) return <div className="py-20 text-center animate-pulse">Synchronizing Stakes...</div>;

  return (
    <div className="space-y-4 w-full">
      <div className="grid gap-3 max-h-[450px] overflow-y-auto pr-2 custom-scrollbar">
        {sortedGames.map((game) => {
          const isSelected = selectedGame?.id === game.id;
          return (
            <button
              key={game.id}
              onClick={() => onSelectGame(game)}
              className={`relative group w-full text-left p-5 rounded-2xl border-2 transition-all duration-300 ${
                isSelected
                  ? 'bg-zinc-900 border-amber-500 shadow-[0_0_30px_rgba(245,158,11,0.15)]'
                  : 'bg-zinc-950/50 border-zinc-900 hover:border-zinc-700 hover:bg-zinc-900'
              }`}
            >
              {game.isMustWin && (
                <span className="absolute -top-[2px] right-4 px-3 py-1 rounded-b-lg bg-amber-500 text-black text-[9px] font-black uppercase tracking-widest shadow-lg z-10 animate-pulse">
                    Must Win
                </span>
              )}

              <div className="flex items-center justify-between gap-6">
                <div className="flex-1 flex flex-col items-center gap-3">
                    <img src={`https://avatar.vercel.sh/${encodeURIComponent(game.homeTeam)}.png?size=80`} className={`w-12 h-12 rounded-full border-2 ${isSelected ? 'border-amber-500' : 'border-zinc-800'}`} />
                    <span className={`text-xs font-black uppercase tracking-tighter ${isSelected ? 'text-white' : 'text-zinc-400'}`}>{game.homeTeam}</span>
                </div>
                <div className="flex flex-col items-center justify-center min-w-[100px]">
                   <span className="text-[10px] font-black text-zinc-700 mb-1.5 uppercase tracking-widest">Kickoff</span>
                   <span className="text-[11px] text-white font-black uppercase bg-zinc-900 px-3 py-1 rounded-md border border-zinc-800 tracking-wider">
                       {game.time}
                   </span>
                   {game.playoffImplications && (
                       <span className="text-[8px] font-bold text-amber-500/60 uppercase mt-2 text-center leading-tight">
                           {game.playoffImplications}
                       </span>
                   )}
                </div>
                <div className="flex-1 flex flex-col items-center gap-3">
                    <img src={`https://avatar.vercel.sh/${encodeURIComponent(game.awayTeam)}.png?size=80`} className={`w-12 h-12 rounded-full border-2 ${isSelected ? 'border-amber-500' : 'border-zinc-800'}`} />
                    <span className={`text-xs font-black uppercase tracking-tighter ${isSelected ? 'text-white' : 'text-zinc-400'}`}>{game.awayTeam}</span>
                </div>
              </div>
            </button>
          );
        })}
      </div>
    </div>
  );
});
